const reminders = $input.first().json.reminders || [];
const summary = $input.first().json.summary || {};
return reminders.map(reminder => ({ json: { ...reminder, summary } }));

const r = $input.first().json;
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Payment Reminder</title></head><body style="margin:0;padding:20px;font-family:Arial,sans-serif;background:#f4f4f5"><div style="max-width:600px;margin:0 auto;background:#fff;border-radius:8px;overflow:hidden"><div style="background:linear-gradient(135deg,#0ea5e9,#0284c7);padding:30px;text-align:center"><h1 style="color:#fff;margin:0">Payment Reminder</h1></div><div style="padding:30px"><p>Dear <strong>${r.customerName}</strong>,</p><p>This is a friendly reminder that you have an upcoming payment due:</p><div style="background:#f8fafc;padding:20px;border-radius:8px;margin:20px 0"><p><strong>Invoice:</strong> #${r.invoiceId}</p><p><strong>Amount Due:</strong> $${r.amountDue?.toFixed(2) || '0.00'}</p><p><strong>Due Date:</strong> ${r.dueDate}</p><p><strong>Days Until Due:</strong> ${r.daysUntilDue} days</p></div><p>Please ensure payment is made by the due date to avoid any late fees.</p><p>If you have already made this payment, please disregard this reminder.</p><p style="margin-top:30px">Best regards,<br><strong>Your Company Name</strong></p></div><div style="background:#f1f5f9;padding:20px;text-align:center;font-size:12px;color:#64748b"><p>Questions? Contact us at accounts@yourcompany.com</p></div></div></body></html>`;
return [{ json: { ...r, emailHtml: html } }];

const items = $input.all();
const results = {
  success: true,
  emailsSent: items.length,
  timestamp: new Date().toISOString(),
  details: items.map(item => ({
    customerName: item.json.customerName,
    customerEmail: item.json.customerEmail,
    invoiceId: item.json.invoiceId,
    status: 'sent'
  }))
};
return [{ json: results }];
